  }
}

@media (max-width: 768px) {
  :root {
    --text-6xl: 2.5rem;
    --text-5xl: 2rem;
    --text-4xl: 1.75rem;
    --text-3xl: 1.5rem;
  }

  .header-nav {
    display: none;
  }

  .header-actions .btn--secondary,
  .header-actions .btn--primary {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .hero {
    min-height: 400px;
  }

  .hero__image {
    display: none;
  }

  .promo-grid,
  .promo-grid--reverse {
    grid-template-columns: 1fr;
    direction: ltr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .tiers-grid {
    grid-template-columns: 1fr;
  }

  .partners-grid {
    grid-template-columns: 1fr;
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .store-layout {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    display: none;
  }

  .footer-accordion {
    display: block;
  }

  .cookie-banner {
    flex-direction: column;
