  }

  .search-bar {
    flex-direction: column;
  }

  .search-controls__actions {
    justify-content: center;
  }

  .map-container {
    aspect-ratio: 4 / 3;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--space-4);
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .app-buttons {
    flex-direction: column;
