/* ============================================
   GreenBean Coffee — Design System & Styles
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Brand Colors */
  --color-primary: #00824A;
  --color-primary-hover: #006B3D;
  --color-primary-light: #E8F5EE;
  --color-primary-lighter: #F0FAF4;
  --color-dark-forest: #32462F;
  --color-warm-cream: #F3CEA1;
  --color-warm-cream-light: #FBF3E0;
  --color-coffee-brown: #6F4E37;
  --color-coffee-dark: #4A3228;
  --color-coffee-light: #D4A574;

  /* Neutral Colors */
  --color-bg: #FAFAF5;
  --color-surface: #FFFFFF;
  --color-text: #1E2D1E;
  --color-text-secondary: #5A6B5A;
  --color-text-muted: #8A9A8A;
  --color-border: #E2E0D8;
  --color-border-light: #F0EDE6;

  /* Accent Colors */
  --color-accent-warm: #D4A574;
  --color-accent-mango: #FFB347;
  --color-accent-lavender: #B39DDB;

  /* Semantic */
  --color-error: #D32F2F;
  --color-success: #2E7D32;

  /* Typography */
  --font-heading: 'DM Serif Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Type Scale */
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.06);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.08), 0 8px 10px -6px rgba(0, 0, 0, 0.04);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --container-max: 1280px;
  --container-wide: 1440px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-primary-hover);
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input, select, textarea {
  font-family: inherit;
  font-size: inherit;
}

/* Focus styles */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: #fff;
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  z-index: 10000;
  font-size: var(--text-sm);
  font-weight: 600;
}

.skip-link:focus {
  top: var(--space-4);
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.2;
  color: var(--color-text);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); }

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container--wide {
  max-width: var(--container-wide);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1.5;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
  min-height: 44px;
}

.btn--primary {
  background: var(--color-primary);
  color: #fff;
  border: 2px solid var(--color-primary);
}

.btn--primary:hover {
  background: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
  color: #fff;
}

.btn--secondary {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn--secondary:hover {
  background: var(--color-primary);
  color: #fff;
}

.btn--dark {
  background: var(--color-dark-forest);
  color: #fff;
  border: 2px solid var(--color-dark-forest);
}

.btn--dark:hover {
  background: #253525;
  border-color: #253525;
}

.btn--cream {
  background: var(--color-warm-cream);
  color: var(--color-coffee-dark);
  border: 2px solid var(--color-warm-cream);
}

.btn--cream:hover {
  background: #ebc488;
  border-color: #ebc488;
}

.btn--ghost {
  background: transparent;
  color: var(--color-primary);
  border: none;
  padding: var(--space-2) var(--space-3);
}

.btn--ghost:hover {
  background: var(--color-primary-light);
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

.btn--sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
  min-height: 36px;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  box-shadow: var(--shadow-sm);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--container-wide);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  color: var(--color-primary);
  text-decoration: none;
  flex-shrink: 0;
}

.header-logo:hover {
  color: var(--color-primary);
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.header-nav a {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: 0.02em;
  transition: color var(--transition-fast);
  position: relative;
  padding: var(--space-1) 0;
}

.header-nav a:hover,
.header-nav a.active {
  color: var(--color-primary);
}

.header-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-primary);
  border-radius: 1px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.header-actions .btn {
  font-size: var(--text-xs);
}

.header-find-store {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
}

.header-find-store:hover {
  color: var(--color-primary);
}

.header-find-store svg {
  width: 18px;
  height: 18px;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: pointer;
}

.menu-toggle svg {
  width: 24px;
  height: 24px;
  color: var(--color-text);
}

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-surface);
  z-index: 99;
  padding: var(--space-6);
  overflow-y: auto;
}

.mobile-nav.is-open {
  display: block;
}

.mobile-nav a {
  display: block;
  padding: var(--space-4) 0;
  font-size: var(--text-lg);
  font-weight: 600;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border-light);
}

.mobile-nav a:hover {
  color: var(--color-primary);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  overflow: hidden;
  min-height: 520px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-primary-lighter) 0%, var(--color-warm-cream-light) 100%);
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 560px;
}

.hero__title {
  font-size: var(--text-6xl);
  margin-bottom: var(--space-6);
  color: var(--color-dark-forest);
}

.hero__cta {
  margin-top: var(--space-6);
}

.hero__image {
  position: absolute;
  right: -5%;
  top: 50%;
  transform: translateY(-50%);
  width: 50%;
  max-width: 600px;
  z-index: 1;
  opacity: 0.15;
}

.hero__image-placeholder {
  width: 100%;
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-coffee-brown) 100%);
  border-radius: var(--radius-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.6);
  font-size: var(--text-2xl);
  font-family: var(--font-heading);
}

/* --- Featured Product --- */
.featured-product {
  padding: var(--space-16) 0;
}

.featured-product__card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.featured-product__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #FF9A56 0%, #FF6B6B 50%, #FFE66D 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
}

.featured-product__content {
  padding: var(--space-10) var(--space-10) var(--space-10) 0;
}

.featured-product__tag {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 600;
  margin-bottom: var(--space-4);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.featured-product__title {
  margin-bottom: var(--space-4);
}

.featured-product__body {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

/* --- Promo Sections --- */
.promo-section {
  padding: var(--space-16) 0;
}

.promo-section--cream {
  background: var(--color-warm-cream-light);
}

.promo-section--green {
  background: var(--color-primary);
  color: #fff;
}

.promo-section--forest {
  background: var(--color-dark-forest);
  color: #fff;
}

.promo-section--forest h2,
.promo-section--green h2 {
  color: #fff;
}

.promo-section--forest p,
.promo-section--green p {
  color: rgba(255,255,255,0.85);
}

.promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
  align-items: center;
}

.promo-grid--reverse {
  direction: rtl;
}

.promo-grid--reverse > * {
  direction: ltr;
}

.promo-image {
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  color: rgba(255,255,255,0.6);
}

.promo-image--mango {
  background: linear-gradient(135deg, #FF9A56 0%, #FFD93D 100%);
}

.promo-image--lavender {
  background: linear-gradient(135deg, #B39DDB 0%, #E1BEE7 50%, #F8BBD0 100%);
}

.promo-image--spring {
  background: linear-gradient(135deg, #81C784 0%, #A5D6A7 50%, #C8E6C9 100%);
}

.promo-image--nondairy {
  background: linear-gradient(135deg, var(--color-primary) 0%, #4CAF50 100%);
}

.promo-content {
  padding: var(--space-4) 0;
}

.promo-content__tag {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 600;
  margin-bottom: var(--space-4);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.promo-content__title {
  margin-bottom: var(--space-4);
}

.promo-content__body {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

.promo-section--forest .promo-content__tag,
.promo-section--green .promo-content__tag {
  background: rgba(255,255,255,0.2);
  color: #fff;
}

/* --- AI Recommendation --- */
.ai-recommendation {
  padding: var(--space-16) 0;
}

.ai-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  background: linear-gradient(135deg, var(--color-dark-forest) 0%, #1a2e1a 100%);
  border-radius: var(--radius-xl);
  overflow: hidden;
  color: #fff;
  padding: var(--space-12);
}

.ai-card h2 {
  color: #fff;
}

.ai-card p {
  color: rgba(255,255,255,0.8);
  font-size: var(--text-lg);
  line-height: 1.7;
}

.ai-card__visual {
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 1;
  background: rgba(255,255,255,0.08);
  border-radius: var(--radius-xl);
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
  color: rgba(255,255,255,0.4);
}

/* --- Menu Page --- */
.menu-page {
  padding: var(--space-8) 0 var(--space-16);
}

.breadcrumb {
  padding: var(--space-4) 0;
  font-size: var(--text-sm);
  color: var(--color-text-muted);
}

.breadcrumb a {
  color: var(--color-text-secondary);
}

.breadcrumb span {
  margin: 0 var(--space-2);
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-8);
  align-items: start;
}

.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-8));
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  box-shadow: var(--shadow-md);
}

.menu-sidebar__section {
  margin-bottom: var(--space-6);
}

.menu-sidebar__heading {
  font-family: var(--font-body);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--color-border-light);
}

.menu-sidebar__link {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.menu-sidebar__link:hover,
.menu-sidebar__link.active {
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-weight: 600;
}

.menu-content__heading {
  font-size: var(--text-3xl);
  margin-bottom: var(--space-8);
  padding-bottom: var(--space-4);
  border-bottom: 2px solid var(--color-primary-light);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-6);
  margin-bottom: var(--space-12);
}

.menu-item {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.menu-item:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.menu-item__image {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  color: rgba(255,255,255,0.6);
  font-size: var(--text-lg);
}

.menu-item__image--coffee {
  background: linear-gradient(135deg, #8D6E63 0%, #6F4E37 100%);
}

.menu-item__image--cold {
  background: linear-gradient(135deg, #4FC3F7 0%, #0288D1 100%);
}

.menu-item__image--matcha {
  background: linear-gradient(135deg, #66BB6A 0%, #388E3C 100%);
}

.menu-item__image--refresher {
  background: linear-gradient(135deg, #FF7043 0%, #F4511E 100%);
}

.menu-item__image--food {
  background: linear-gradient(135deg, #FFB74D 0%, #F57C00 100%);
}

.menu-item__image--bakery {
  background: linear-gradient(135deg, #D4A574 0%, #A1887F 100%);
}

.menu-item__name {
  padding: var(--space-3) var(--space-4);
  font-weight: 600;
  font-size: var(--text-sm);
}

.menu-section-divider {
  margin: var(--space-12) 0 var(--space-8);
  padding-top: var(--space-8);
  border-top: 1px solid var(--color-border-light);
}

/* --- Rewards Page --- */
.rewards-hero {
  padding: var(--space-16) 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%);
  color: #fff;
  text-align: center;
}

.rewards-hero h1 {
  color: #fff;
  font-size: var(--text-5xl);
  margin-bottom: var(--space-4);
}

.rewards-hero p {
  color: rgba(255,255,255,0.85);
  font-size: var(--text-lg);
  max-width: 600px;
  margin: 0 auto var(--space-8);
}

.how-it-works {
  padding: var(--space-16) 0;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
  margin-top: var(--space-12);
}

.step-card {
  text-align: center;
  padding: var(--space-8);
}

.step-card__number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  margin: 0 auto var(--space-6);
}

.step-card h3 {
  margin-bottom: var(--space-3);
}

.step-card p {
  color: var(--color-text-secondary);
  line-height: 1.7;
}

/* Status Tiers */
.status-tiers {
  padding: var(--space-16) 0;
  background: var(--color-primary-lighter);
}

.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  margin-top: var(--space-12);
}

.tier-card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
  transition: all var(--transition-base);
}

.tier-card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

.tier-card--gold {
  border: 2px solid #FFD700;
}

.tier-card--reserve {
  border: 2px solid var(--color-coffee-dark);
  background: linear-gradient(180deg, #3a2a1e 0%, var(--color-dark-forest) 100%);
  color: #fff;
}

.tier-card--reserve h3,
.tier-card--reserve h4 {
  color: #fff;
}

.tier-card--reserve p,
.tier-card--reserve li {
  color: rgba(255,255,255,0.85);
}

.tier-card__badge {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: var(--space-4);
}

.tier-card--green .tier-card__badge {
  background: var(--color-primary-light);
  color: var(--color-primary);
}

.tier-card--gold .tier-card__badge {
  background: #FFF8E1;
  color: #F9A825;
}

.tier-card--reserve .tier-card__badge {
  background: rgba(255,255,255,0.15);
  color: var(--color-warm-cream);
}

.tier-card h3 {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-2);
}

.tier-card__threshold {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  margin-bottom: var(--space-6);
}

.tier-card--reserve .tier-card__threshold {
  color: rgba(255,255,255,0.6);
}

.tier-card__benefits {
  list-style: none;
}

.tier-card__benefits li {
  padding: var(--space-2) 0;
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.tier-card__benefits li::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-primary);
  flex-shrink: 0;
}

.tier-card--reserve .tier-card__benefits li::before {
  background: var(--color-warm-cream);
}

/* Redemption Tabs */
.redemption-section {
  padding: var(--space-16) 0;
}

.redemption-tabs {
  display: flex;
  gap: var(--space-2);
  overflow-x: auto;
  padding-bottom: var(--space-4);
  margin-bottom: var(--space-8);
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}

.redemption-tab {
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  white-space: nowrap;
  background: var(--color-surface);
  color: var(--color-text-secondary);
  border: 2px solid var(--color-border);
  cursor: pointer;
  transition: all var(--transition-base);
  min-height: 44px;
  display: flex;
  align-items: center;
}

.redemption-tab:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.redemption-tab.active {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}

.redemption-content {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-md);
  min-height: 200px;
}

.redemption-panel {
  display: none;
}

.redemption-panel.active {
  display: block;
  animation: fadeIn var(--transition-base);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-panel__stars {
  font-size: var(--text-4xl);
  color: var(--color-primary);
  font-family: var(--font-heading);
  margin-bottom: var(--space-4);
}

.redemption-panel__reward {
  font-size: var(--text-xl);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.redemption-panel__value {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
}

/* Partnerships */
.partnerships {
  padding: var(--space-16) 0;
  background: var(--color-warm-cream-light);
}

.partners-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
  margin-top: var(--space-12);
}

.partner-card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-md);
  display: flex;
  gap: var(--space-6);
  align-items: start;
}

.partner-card__icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-lg);
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: var(--text-2xl);
  color: var(--color-primary);
}

.partner-card h4 {
  margin-bottom: var(--space-2);
}

.partner-card p {
  color: var(--color-text-secondary);
  font-size: var(--text-sm);
  line-height: 1.6;
}

/* App Download */
.app-download {
  padding: var(--space-16) 0;
  text-align: center;
}

.app-download__visual {
  max-width: 400px;
  margin: var(--space-8) auto;
  aspect-ratio: 3 / 4;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%);
  border-radius: var(--radius-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.5);
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
}

.app-buttons {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  margin-top: var(--space-6);
}

/* Terms */
.terms-section {
  padding: var(--space-8) 0 var(--space-16);
}

.terms-section p {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  line-height: 1.7;
}

/* --- Gift Cards Page --- */
.gift-hero {
  padding: var(--space-16) 0;
  background: linear-gradient(135deg, var(--color-warm-cream-light) 0%, var(--color-primary-lighter) 100%);
  text-align: center;
}

.gift-hero h1 {
  font-size: var(--text-5xl);
  margin-bottom: var(--space-4);
}

.gift-hero p {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  max-width: 600px;
  margin: 0 auto;
}

/* Carousel */
.carousel-section {
  padding: var(--space-12) 0;
}

.carousel-section__title {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-6);
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: var(--space-2) 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-card {
  flex: 0 0 200px;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
}

.carousel-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.carousel-card__image {
  aspect-ratio: 3 / 2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.8);
  text-align: center;
  padding: var(--space-2);
}

.carousel-card__name {
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm);
  font-weight: 600;
  text-align: center;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-surface);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 5;
  border: 1px solid var(--color-border);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}

.carousel-btn--prev {
  left: -22px;
}

.carousel-btn--next {
  right: -22px;
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

/* Card color variants */
.card-bg--spring { background: linear-gradient(135deg, #81C784 0%, #4CAF50 100%); }
.card-bg--perk { background: linear-gradient(135deg, var(--color-primary) 0%, #00A85B 100%); }
.card-bg--friends { background: linear-gradient(135deg, #7E57C2 0%, #AB47BC 100%); }
.card-bg--thanks { background: linear-gradient(135deg, #42A5F5 0%, #1E88E5 100%); }
.card-bg--star { background: linear-gradient(135deg, #FFD54F 0%, #FFB300 100%); }
.card-bg--great-work { background: linear-gradient(135deg, #EF5350 0%, #C62828 100%); }
.card-bg--birthday { background: linear-gradient(135deg, #FF7043 0%, #E64A19 100%); }
.card-bg--celebrate { background: linear-gradient(135deg, #EC407A 0%, #C2185B 100%); }
.card-bg--cheers { background: linear-gradient(135deg, #FFA726 0%, #EF6C00 100%); }
.card-bg--encourage { background: linear-gradient(135deg, #26C6DA 0%, #00838F 100%); }
.card-bg--workplace { background: linear-gradient(135deg, #5C6BC0 0%, #283593 100%); }
.card-bg--greenbean { background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%); }
.card-bg--cafe { background: linear-gradient(135deg, #8D6E63 0%, #4E342E 100%); }
.card-bg--heritage { background: linear-gradient(135deg, #32462F 0%, #1a2e1a 100%); }
.card-bg--yay { background: linear-gradient(135deg, #FF80AB 0%, #F50057 100%); }
.card-bg--above { background: linear-gradient(135deg, #546E7A 0%, #263238 100%); }
.card-bg--you-got { background: linear-gradient(135deg, #9CCC65 0%, #558B2F 100%); }
.card-bg--treat { background: linear-gradient(135deg, #FFAB91 0%, #BF360C 100%); }

/* Business Gifting */
.business-gifting {
  padding: var(--space-16) 0;
  background: var(--color-dark-forest);
  color: #fff;
}

.business-gifting h2 {
  color: #fff;
  margin-bottom: var(--space-4);
}

.business-gifting p {
  color: rgba(255,255,255,0.8);
  font-size: var(--text-lg);
  line-height: 1.7;
  max-width: 600px;
  margin-bottom: var(--space-8);
}

/* eGift Info */
.egift-info {
  padding: var(--space-16) 0;
}

.egift-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.egift-content p {
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-bottom: var(--space-4);
}

.egift-actions {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  margin-top: var(--space-6);
}

/* FAQ */
.faq-section {
  padding: var(--space-16) 0;
  background: var(--color-primary-lighter);
}

.faq-list {
  max-width: 700px;
  margin: var(--space-8) auto 0;
}

.faq-item {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-3);
  overflow: hidden;
}

.faq-item__question {
  width: 100%;
  text-align: left;
  padding: var(--space-5) var(--space-6);
  font-size: var(--text-base);
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  min-height: 44px;
}

.faq-item__question:hover {
  background: var(--color-primary-lighter);
}

.faq-item__icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.faq-item.is-open .faq-item__icon {
  transform: rotate(180deg);
}

.faq-item__answer {
  display: none;
  padding: 0 var(--space-6) var(--space-5);
  color: var(--color-text-secondary);
  line-height: 1.7;
}

.faq-item.is-open .faq-item__answer {
  display: block;
}

/* --- Store Locator --- */
.store-locator {
  padding: var(--space-4) 0 var(--space-16);
}

.search-controls {
  background: var(--color-surface);
  padding: var(--space-6);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-md);
  margin-bottom: var(--space-6);
}

.search-bar {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  margin-bottom: var(--space-4);
}

.search-input-wrapper {
  flex: 1;
  position: relative;
}

.search-input-wrapper svg {
  position: absolute;
  left: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  color: var(--color-text-muted);
}

.search-input {
  width: 100%;
  padding: var(--space-3) var(--space-4) var(--space-3) var(--space-10);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--text-base);
  transition: border-color var(--transition-fast);
  min-height: 44px;
  background: var(--color-bg);
}

.search-input:focus {
  border-color: var(--color-primary);
  outline: none;
}

.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  z-index: 10;
  display: none;
  margin-top: var(--space-1);
}

.search-suggestions.is-visible {
  display: block;
}

.search-suggestions li {
  padding: var(--space-3) var(--space-4);
  cursor: pointer;
  font-size: var(--text-sm);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.search-suggestions li:hover {
  background: var(--color-primary-light);
}

.search-controls__actions {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  flex-wrap: wrap;
}

.order-type-toggle {
  display: flex;
  background: var(--color-bg);
  border-radius: var(--radius-full);
  padding: 3px;
  gap: 2px;
}

.order-type-btn {
  padding: var(--space-2) var(--space-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
  min-height: 36px;
  display: flex;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-secondary);
}

.order-type-btn.active {
  background: var(--color-primary);
  color: #fff;
}

.filter-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-secondary);
  background: var(--color-surface);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-height: 36px;
}

.filter-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.filter-btn svg {
  width: 16px;
  height: 16px;
}

/* Filter Panel */
.filter-panel {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  margin-bottom: var(--space-6);
  box-shadow: var(--shadow-md);
  display: none;
}

.filter-panel.is-open {
  display: block;
  animation: slideDown var(--transition-base);
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.filter-panel__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-3);
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  accent-color: var(--color-primary);
  width: 18px;
  height: 18px;
}

/* Map & Results */
.store-layout {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: var(--space-6);
  align-items: start;
}

.map-container {
  background: var(--color-border-light);
  border-radius: var(--radius-xl);
  aspect-ratio: 16 / 10;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  min-height: 400px;
}

.map-placeholder {
  text-align: center;
  color: var(--color-text-muted);
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  margin-bottom: var(--space-3);
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  border-radius: 50% 50% 50% 0;
  background: var(--color-primary);
  transform: rotate(-45deg);
  box-shadow: var(--shadow-md);
}

.map-pin::after {
  content: '';
  width: 12px;
  height: 12px;
  background: #fff;
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.results-list {
  max-height: 600px;
  overflow-y: auto;
}

.store-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  margin-bottom: var(--space-3);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.store-card:hover {
  box-shadow: var(--shadow-md);
}

.store-card__name {
  font-weight: 700;
  font-size: var(--text-base);
  margin-bottom: var(--space-1);
}

.store-card__address {
  color: var(--color-text-secondary);
  font-size: var(--text-sm);
  margin-bottom: var(--space-2);
}

.store-card__hours {
  color: var(--color-primary);
  font-size: var(--text-sm);
  font-weight: 600;
  margin-bottom: var(--space-3);
}

.store-card__features {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.store-feature {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-2);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: 600;
}

/* --- Footer --- */
.site-footer {
  background: var(--color-dark-forest);
  color: rgba(255,255,255,0.8);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-column h4 {
  color: #fff;
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  margin-bottom: var(--space-4);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-column a {
  display: block;
  padding: var(--space-1) 0;
  color: rgba(255,255,255,0.7);
  font-size: var(--text-sm);
  transition: color var(--transition-fast);
}

.footer-column a:hover {
  color: #fff;
}

.footer-accordion {
  display: none;
}

.footer-accordion__item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-accordion__trigger {
  width: 100%;
  text-align: left;
  padding: var(--space-4) 0;
  color: #fff;
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  min-height: 44px;
}

.footer-accordion__icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
}

.footer-accordion__item.is-open .footer-accordion__icon {
  transform: rotate(180deg);
}

.footer-accordion__content {
  display: none;
  padding-bottom: var(--space-4);
}

.footer-accordion__item.is-open .footer-accordion__content {
  display: block;
}

.footer-accordion__content a {
  display: block;
  padding: var(--space-2) 0;
  color: rgba(255,255,255,0.7);
  font-size: var(--text-sm);
}

.footer-accordion__content a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-6);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-bottom p {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-4);
}

.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background: var(--color-primary);
  color: #fff;
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--color-dark-forest);
  color: #fff;
  padding: var(--space-6);
  z-index: 1000;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-8);
}

.cookie-banner.is-hidden {
  display: none;
}

.cookie-banner__content {
  max-width: 600px;
}

.cookie-banner__title {
  font-family: var(--font-heading);
  font-size: var(--text-lg);
  margin-bottom: var(--space-2);
  color: #fff;
}

.cookie-banner__text {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.8);
  line-height: 1.6;
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
}

/* --- Utilities --- */
.text-center { text-align: center; }
.text-primary { color: var(--color-primary); }
.mt-4 { margin-top: var(--space-4); }
.mt-8 { margin-top: var(--space-8); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-8 { margin-bottom: var(--space-8); }
.section-title {
  text-align: center;
  margin-bottom: var(--space-4);
}
.section-subtitle {
  text-align: center;
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  max-width: 600px;
  margin: 0 auto var(--space-4);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .featured-product__card {
    grid-template-columns: 1fr;
  }

  .featured-product__image {
    aspect-ratio: 16 / 9;
  }

  .featured-product__content {
    padding: var(--space-8);
  }

  .promo-grid {
    gap: var(--space-6);
  }

  .ai-card {
    grid-template-columns: 1fr;
    padding: var(--space-8);
  }

  .menu-layout {
    grid-template-columns: 220px 1fr;
    gap: var(--space-6);
  }

  .store-layout {
    grid-template-columns: 1fr;
  }

  .results-list {
    max-height: none;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --text-6xl: 2.5rem;
    --text-5xl: 2rem;
    --text-4xl: 1.75rem;
    --text-3xl: 1.5rem;
  }

  .header-nav {
    display: none;
  }

  .header-actions .btn--secondary,
  .header-actions .btn--primary {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .hero {
    min-height: 400px;
  }

  .hero__image {
    display: none;
  }

  .promo-grid,
  .promo-grid--reverse {
    grid-template-columns: 1fr;
    direction: ltr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .tiers-grid {
    grid-template-columns: 1fr;
  }

  .partners-grid {
    grid-template-columns: 1fr;
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .store-layout {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    display: none;
  }

  .footer-accordion {
    display: block;
  }

  .cookie-banner {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .search-bar {
    flex-direction: column;
  }

  .search-controls__actions {
    justify-content: center;
  }

  .map-container {
    aspect-ratio: 4 / 3;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--space-4);
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .app-buttons {
    flex-direction: column;
    align-items: center;
  }

  .carousel-card {
    flex: 0 0 160px;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ============================================
   GreenBean Coffee — Design System & Styles
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Brand Colors */
  --color-primary: #00824A;
  --color-primary-hover: #006B3D;
  --color-primary-light: #E8F5EE;
  --color-primary-lighter: #F0FAF4;
  --color-dark-forest: #32462F;
  --color-warm-cream: #F3CEA1;
  --color-warm-cream-light: #FBF3E0;
  --color-coffee-brown: #6F4E37;
  --color-coffee-dark: #4A3228;
  --color-coffee-light: #D4A574;

  /* Neutral Colors */
  --color-bg: #FAFAF5;
  --color-surface: #FFFFFF;
  --color-text: #1E2D1E;
  --color-text-secondary: #5A6B5A;
  --color-text-muted: #8A9A8A;
  --color-border: #E2E0D8;
  --color-border-light: #F0EDE6;

  /* Accent Colors */
  --color-accent-warm: #D4A574;
  --color-accent-mango: #FFB347;
  --color-accent-lavender: #B39DDB;

  /* Semantic */
  --color-error: #D32F2F;
  --color-success: #2E7D32;

  /* Typography */
  --font-heading: 'DM Serif Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Type Scale */
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.06);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.08), 0 8px 10px -6px rgba(0, 0, 0, 0.04);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --container-max: 1280px;
  --container-wide: 1440px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-primary-hover);
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input, select, textarea {
  font-family: inherit;
  font-size: inherit;
}

/* Focus styles */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: #fff;
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  z-index: 10000;
  font-size: var(--text-sm);
  font-weight: 600;
}

.skip-link:focus {
  top: var(--space-4);
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.2;
  color: var(--color-text);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); }

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container--wide {
  max-width: var(--container-wide);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1.5;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
  min-height: 44px;
}

.btn--primary {
  background: var(--color-primary);
  color: #fff;
  border: 2px solid var(--color-primary);
}

.btn--primary:hover {
  background: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
  color: #fff;
}

.btn--secondary {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn--secondary:hover {
  background: var(--color-primary);
  color: #fff;
}

.btn--dark {
  background: var(--color-dark-forest);
  color: #fff;
  border: 2px solid var(--color-dark-forest);
}

.btn--dark:hover {
  background: #253525;
  border-color: #253525;
}

.btn--cream {
  background: var(--color-warm-cream);
  color: var(--color-coffee-dark);
  border: 2px solid var(--color-warm-cream);
}

.btn--cream:hover {
  background: #ebc488;
  border-color: #ebc488;
}

.btn--ghost {
  background: transparent;
  color: var(--color-primary);
  border: none;
  padding: var(--space-2) var(--space-3);
}

.btn--ghost:hover {
  background: var(--color-primary-light);
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

.btn--sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
  min-height: 36px;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  box-shadow: var(--shadow-sm);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--container-wide);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  color: var(--color-primary);
  text-decoration: none;
  flex-shrink: 0;
}

.header-logo:hover {
  color: var(--color-primary);
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.header-nav a {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: 0.02em;
  transition: color var(--transition-fast);
  position: relative;
  padding: var(--space-1) 0;
}

.header-nav a:hover,
.header-nav a.active {
  color: var(--color-primary);
}

.header-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-primary);
  border-radius: 1px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.header-actions .btn {
  font-size: var(--text-xs);
}

.header-find-store {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
}

.header-find-store:hover {
  color: var(--color-primary);
}

.header-find-store svg {
  width: 18px;
  height: 18px;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: pointer;
}

.menu-toggle svg {
  width: 24px;
  height: 24px;
  color: var(--color-text);
}

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-surface);
  z-index: 99;
  padding: var(--space-6);
  overflow-y: auto;
}

.mobile-nav.is-open {
  display: block;
}

.mobile-nav a {
  display: block;
  padding: var(--space-4) 0;
  font-size: var(--text-lg);
  font-weight: 600;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border-light);
}

.mobile-nav a:hover {
  color: var(--color-primary);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  overflow: hidden;
  min-height: 520px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-primary-lighter) 0%, var(--color-warm-cream-light) 100%);
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 560px;
}

.hero__title {
  font-size: var(--text-6xl);
  margin-bottom: var(--space-6);
  color: var(--color-dark-forest);
}

.hero__cta {
  margin-top: var(--space-6);
}

.hero__image {
  position: absolute;
  right: -5%;
  top: 50%;
  transform: translateY(-50%);
  width: 50%;
  max-width: 600px;
  z-index: 1;
  opacity: 0.15;
}

.hero__image-placeholder {
  width: 100%;
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-coffee-brown) 100%);
  border-radius: var(--radius-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.6);
  font-size: var(--text-2xl);
  font-family: var(--font-heading);
}

/* --- Featured Product --- */
.featured-product {
  padding: var(--space-16) 0;
}

.featured-product__card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.featured-product__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #FF9A56 0%, #FF6B6B 50%, #FFE66D 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
}

.featured-product__content {
  padding: var(--space-10) var(--space-10) var(--space-10) 0;
}

.featured-product__tag {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 600;
  margin-bottom: var(--space-4);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.featured-product__title {
  margin-bottom: var(--space-4);
}

.featured-product__body {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

/* --- Promo Sections --- */
.promo-section {
  padding: var(--space-16) 0;
}

.promo-section--cream {
  background: var(--color-warm-cream-light);
}

.promo-section--green {
  background: var(--color-primary);
  color: #fff;
}

.promo-section--forest {
  background: var(--color-dark-forest);
  color: #fff;
}

.promo-section--forest h2,
.promo-section--green h2 {
  color: #fff;
}

.promo-section--forest p,
.promo-section--green p {
  color: rgba(255,255,255,0.85);
}

.promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
  align-items: center;
}

.promo-grid--reverse {
  direction: rtl;
}

.promo-grid--reverse > * {
  direction: ltr;
}

.promo-image {
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  color: rgba(255,255,255,0.6);
}

.promo-image--mango {
  background: linear-gradient(135deg, #FF9A56 0%, #FFD93D 100%);
}

.promo-image--lavender {
  background: linear-gradient(135deg, #B39DDB 0%, #E1BEE7 50%, #F8BBD0 100%);
}

.promo-image--spring {
  background: linear-gradient(135deg, #81C784 0%, #A5D6A7 50%, #C8E6C9 100%);
}

.promo-image--nondairy {
  background: linear-gradient(135deg, var(--color-primary) 0%, #4CAF50 100%);
}

.promo-content {
  padding: var(--space-4) 0;
}

.promo-content__tag {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 600;
  margin-bottom: var(--space-4);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.promo-content__title {
  margin-bottom: var(--space-4);
}

.promo-content__body {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

.promo-section--forest .promo-content__tag,
.promo-section--green .promo-content__tag {
  background: rgba(255,255,255,0.2);
  color: #fff;
}

/* --- AI Recommendation --- */
.ai-recommendation {
  padding: var(--space-16) 0;
}

.ai-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  background: linear-gradient(135deg, var(--color-dark-forest) 0%, #1a2e1a 100%);
  border-radius: var(--radius-xl);
  overflow: hidden;
  color: #fff;
  padding: var(--space-12);
}

.ai-card h2 {
  color: #fff;
}

.ai-card p {
  color: rgba(255,255,255,0.8);
  font-size: var(--text-lg);
  line-height: 1.7;
}

.ai-card__visual {
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 1;
  background: rgba(255,255,255,0.08);
  border-radius: var(--radius-xl);
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
  color: rgba(255,255,255,0.4);
}

/* --- Menu Page --- */
.menu-page {
  padding: var(--space-8) 0 var(--space-16);
}

.breadcrumb {
  padding: var(--space-4) 0;
  font-size: var(--text-sm);
  color: var(--color-text-muted);
}

.breadcrumb a {
  color: var(--color-text-secondary);
}

.breadcrumb span {
  margin: 0 var(--space-2);
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-8);
  align-items: start;
}

.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-8));
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  box-shadow: var(--shadow-md);
}

.menu-sidebar__section {
  margin-bottom: var(--space-6);
}

.menu-sidebar__heading {
  font-family: var(--font-body);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--color-border-light);
}

.menu-sidebar__link {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.menu-sidebar__link:hover,
.menu-sidebar__link.active {
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-weight: 600;
}

.menu-content__heading {
  font-size: var(--text-3xl);
  margin-bottom: var(--space-8);
  padding-bottom: var(--space-4);
  border-bottom: 2px solid var(--color-primary-light);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-6);
  margin-bottom: var(--space-12);
}

.menu-item {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.menu-item:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.menu-item__image {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  color: rgba(255,255,255,0.6);
  font-size: var(--text-lg);
}

.menu-item__image--coffee {
  background: linear-gradient(135deg, #8D6E63 0%, #6F4E37 100%);
}

.menu-item__image--cold {
  background: linear-gradient(135deg, #4FC3F7 0%, #0288D1 100%);
}

.menu-item__image--matcha {
  background: linear-gradient(135deg, #66BB6A 0%, #388E3C 100%);
}

.menu-item__image--refresher {
  background: linear-gradient(135deg, #FF7043 0%, #F4511E 100%);
}

.menu-item__image--food {
  background: linear-gradient(135deg, #FFB74D 0%, #F57C00 100%);
}

.menu-item__image--bakery {
  background: linear-gradient(135deg, #D4A574 0%, #A1887F 100%);
}

.menu-item__name {
  padding: var(--space-3) var(--space-4);
  font-weight: 600;
  font-size: var(--text-sm);
}

.menu-section-divider {
  margin: var(--space-12) 0 var(--space-8);
  padding-top: var(--space-8);
  border-top: 1px solid var(--color-border-light);
}

/* --- Rewards Page --- */
.rewards-hero {
  padding: var(--space-16) 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%);
  color: #fff;
  text-align: center;
}

.rewards-hero h1 {
  color: #fff;
  font-size: var(--text-5xl);
  margin-bottom: var(--space-4);
}

.rewards-hero p {
  color: rgba(255,255,255,0.85);
  font-size: var(--text-lg);
  max-width: 600px;
  margin: 0 auto var(--space-8);
}

.how-it-works {
  padding: var(--space-16) 0;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
  margin-top: var(--space-12);
}

.step-card {
  text-align: center;
  padding: var(--space-8);
}

.step-card__number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  margin: 0 auto var(--space-6);
}

.step-card h3 {
  margin-bottom: var(--space-3);
}

.step-card p {
  color: var(--color-text-secondary);
  line-height: 1.7;
}

/* Status Tiers */
.status-tiers {
  padding: var(--space-16) 0;
  background: var(--color-primary-lighter);
}

.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  margin-top: var(--space-12);
}

.tier-card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
  transition: all var(--transition-base);
}

.tier-card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

.tier-card--gold {
  border: 2px solid #FFD700;
}

.tier-card--reserve {
  border: 2px solid var(--color-coffee-dark);
  background: linear-gradient(180deg, #3a2a1e 0%, var(--color-dark-forest) 100%);
  color: #fff;
}

.tier-card--reserve h3,
.tier-card--reserve h4 {
  color: #fff;
}

.tier-card--reserve p,
.tier-card--reserve li {
  color: rgba(255,255,255,0.85);
}

.tier-card__badge {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: var(--space-4);
}

.tier-card--green .tier-card__badge {
  background: var(--color-primary-light);
  color: var(--color-primary);
}

.tier-card--gold .tier-card__badge {
  background: #FFF8E1;
  color: #F9A825;
}

.tier-card--reserve .tier-card__badge {
  background: rgba(255,255,255,0.15);
  color: var(--color-warm-cream);
}

.tier-card h3 {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-2);
}

.tier-card__threshold {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  margin-bottom: var(--space-6);
}

.tier-card--reserve .tier-card__threshold {
  color: rgba(255,255,255,0.6);
}

.tier-card__benefits {
  list-style: none;
}

.tier-card__benefits li {
  padding: var(--space-2) 0;
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.tier-card__benefits li::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-primary);
  flex-shrink: 0;
}

.tier-card--reserve .tier-card__benefits li::before {
  background: var(--color-warm-cream);
}

/* Redemption Tabs */
.redemption-section {
  padding: var(--space-16) 0;
}

.redemption-tabs {
  display: flex;
  gap: var(--space-2);
  overflow-x: auto;
  padding-bottom: var(--space-4);
  margin-bottom: var(--space-8);
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}

.redemption-tab {
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  white-space: nowrap;
  background: var(--color-surface);
  color: var(--color-text-secondary);
  border: 2px solid var(--color-border);
  cursor: pointer;
  transition: all var(--transition-base);
  min-height: 44px;
  display: flex;
  align-items: center;
}

.redemption-tab:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.redemption-tab.active {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}

.redemption-content {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-md);
  min-height: 200px;
}

.redemption-panel {
  display: none;
}

.redemption-panel.active {
  display: block;
  animation: fadeIn var(--transition-base);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-panel__stars {
  font-size: var(--text-4xl);
  color: var(--color-primary);
  font-family: var(--font-heading);
  margin-bottom: var(--space-4);
}

.redemption-panel__reward {
  font-size: var(--text-xl);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.redemption-panel__value {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
}

/* Partnerships */
.partnerships {
  padding: var(--space-16) 0;
  background: var(--color-warm-cream-light);
}

.partners-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
  margin-top: var(--space-12);
}

.partner-card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-md);
  display: flex;
  gap: var(--space-6);
  align-items: start;
}

.partner-card__icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-lg);
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: var(--text-2xl);
  color: var(--color-primary);
}

.partner-card h4 {
  margin-bottom: var(--space-2);
}

.partner-card p {
  color: var(--color-text-secondary);
  font-size: var(--text-sm);
  line-height: 1.6;
}

/* App Download */
.app-download {
  padding: var(--space-16) 0;
  text-align: center;
}

.app-download__visual {
  max-width: 400px;
  margin: var(--space-8) auto;
  aspect-ratio: 3 / 4;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%);
  border-radius: var(--radius-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.5);
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
}

.app-buttons {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  margin-top: var(--space-6);
}

/* Terms */
.terms-section {
  padding: var(--space-8) 0 var(--space-16);
}

.terms-section p {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  line-height: 1.7;
}

/* --- Gift Cards Page --- */
.gift-hero {
  padding: var(--space-16) 0;
  background: linear-gradient(135deg, var(--color-warm-cream-light) 0%, var(--color-primary-lighter) 100%);
  text-align: center;
}

.gift-hero h1 {
  font-size: var(--text-5xl);
  margin-bottom: var(--space-4);
}

.gift-hero p {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  max-width: 600px;
  margin: 0 auto;
}

/* Carousel */
.carousel-section {
  padding: var(--space-12) 0;
}

.carousel-section__title {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-6);
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: var(--space-2) 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-card {
  flex: 0 0 200px;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
}

.carousel-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.carousel-card__image {
  aspect-ratio: 3 / 2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.8);
  text-align: center;
  padding: var(--space-2);
}

.carousel-card__name {
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm);
  font-weight: 600;
  text-align: center;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-surface);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 5;
  border: 1px solid var(--color-border);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}

.carousel-btn--prev {
  left: -22px;
}

.carousel-btn--next {
  right: -22px;
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

/* Card color variants */
.card-bg--spring { background: linear-gradient(135deg, #81C784 0%, #4CAF50 100%); }
.card-bg--perk { background: linear-gradient(135deg, var(--color-primary) 0%, #00A85B 100%); }
.card-bg--friends { background: linear-gradient(135deg, #7E57C2 0%, #AB47BC 100%); }
.card-bg--thanks { background: linear-gradient(135deg, #42A5F5 0%, #1E88E5 100%); }
.card-bg--star { background: linear-gradient(135deg, #FFD54F 0%, #FFB300 100%); }
.card-bg--great-work { background: linear-gradient(135deg, #EF5350 0%, #C62828 100%); }
.card-bg--birthday { background: linear-gradient(135deg, #FF7043 0%, #E64A19 100%); }
.card-bg--celebrate { background: linear-gradient(135deg, #EC407A 0%, #C2185B 100%); }
.card-bg--cheers { background: linear-gradient(135deg, #FFA726 0%, #EF6C00 100%); }
.card-bg--encourage { background: linear-gradient(135deg, #26C6DA 0%, #00838F 100%); }
.card-bg--workplace { background: linear-gradient(135deg, #5C6BC0 0%, #283593 100%); }
.card-bg--greenbean { background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%); }
.card-bg--cafe { background: linear-gradient(135deg, #8D6E63 0%, #4E342E 100%); }
.card-bg--heritage { background: linear-gradient(135deg, #32462F 0%, #1a2e1a 100%); }
.card-bg--yay { background: linear-gradient(135deg, #FF80AB 0%, #F50057 100%); }
.card-bg--above { background: linear-gradient(135deg, #546E7A 0%, #263238 100%); }
.card-bg--you-got { background: linear-gradient(135deg, #9CCC65 0%, #558B2F 100%); }
.card-bg--treat { background: linear-gradient(135deg, #FFAB91 0%, #BF360C 100%); }

/* Business Gifting */
.business-gifting {
  padding: var(--space-16) 0;
  background: var(--color-dark-forest);
  color: #fff;
}

.business-gifting h2 {
  color: #fff;
  margin-bottom: var(--space-4);
}

.business-gifting p {
  color: rgba(255,255,255,0.8);
  font-size: var(--text-lg);
  line-height: 1.7;
  max-width: 600px;
  margin-bottom: var(--space-8);
}

/* eGift Info */
.egift-info {
  padding: var(--space-16) 0;
}

.egift-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.egift-content p {
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-bottom: var(--space-4);
}

.egift-actions {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  margin-top: var(--space-6);
}

/* FAQ */
.faq-section {
  padding: var(--space-16) 0;
  background: var(--color-primary-lighter);
}

.faq-list {
  max-width: 700px;
  margin: var(--space-8) auto 0;
}

.faq-item {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-3);
  overflow: hidden;
}

.faq-item__question {
  width: 100%;
  text-align: left;
  padding: var(--space-5) var(--space-6);
  font-size: var(--text-base);
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  min-height: 44px;
}

.faq-item__question:hover {
  background: var(--color-primary-lighter);
}

.faq-item__icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.faq-item.is-open .faq-item__icon {
  transform: rotate(180deg);
}

.faq-item__answer {
  display: none;
  padding: 0 var(--space-6) var(--space-5);
  color: var(--color-text-secondary);
  line-height: 1.7;
}

.faq-item.is-open .faq-item__answer {
  display: block;
}

/* --- Store Locator --- */
.store-locator {
  padding: var(--space-4) 0 var(--space-16);
}

.search-controls {
  background: var(--color-surface);
  padding: var(--space-6);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-md);
  margin-bottom: var(--space-6);
}

.search-bar {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  margin-bottom: var(--space-4);
}

.search-input-wrapper {
  flex: 1;
  position: relative;
}

.search-input-wrapper svg {
  position: absolute;
  left: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  color: var(--color-text-muted);
}

.search-input {
  width: 100%;
  padding: var(--space-3) var(--space-4) var(--space-3) var(--space-10);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--text-base);
  transition: border-color var(--transition-fast);
  min-height: 44px;
  background: var(--color-bg);
}

.search-input:focus {
  border-color: var(--color-primary);
  outline: none;
}

.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  z-index: 10;
  display: none;
  margin-top: var(--space-1);
}

.search-suggestions.is-visible {
  display: block;
}

.search-suggestions li {
  padding: var(--space-3) var(--space-4);
  cursor: pointer;
  font-size: var(--text-sm);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.search-suggestions li:hover {
  background: var(--color-primary-light);
}

.search-controls__actions {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  flex-wrap: wrap;
}

.order-type-toggle {
  display: flex;
  background: var(--color-bg);
  border-radius: var(--radius-full);
  padding: 3px;
  gap: 2px;
}

.order-type-btn {
  padding: var(--space-2) var(--space-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
  min-height: 36px;
  display: flex;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-secondary);
}

.order-type-btn.active {
  background: var(--color-primary);
  color: #fff;
}

.filter-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-secondary);
  background: var(--color-surface);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-height: 36px;
}

.filter-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.filter-btn svg {
  width: 16px;
  height: 16px;
}

/* Filter Panel */
.filter-panel {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  margin-bottom: var(--space-6);
  box-shadow: var(--shadow-md);
  display: none;
}

.filter-panel.is-open {
  display: block;
  animation: slideDown var(--transition-base);
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.filter-panel__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-3);
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  accent-color: var(--color-primary);
  width: 18px;
  height: 18px;
}

/* Map & Results */
.store-layout {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: var(--space-6);
  align-items: start;
}

.map-container {
  background: var(--color-border-light);
  border-radius: var(--radius-xl);
  aspect-ratio: 16 / 10;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  min-height: 400px;
}

.map-placeholder {
  text-align: center;
  color: var(--color-text-muted);
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  margin-bottom: var(--space-3);
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  border-radius: 50% 50% 50% 0;
  background: var(--color-primary);
  transform: rotate(-45deg);
  box-shadow: var(--shadow-md);
}

.map-pin::after {
  content: '';
  width: 12px;
  height: 12px;
  background: #fff;
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.results-list {
  max-height: 600px;
  overflow-y: auto;
}

.store-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  margin-bottom: var(--space-3);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.store-card:hover {
  box-shadow: var(--shadow-md);
}

.store-card__name {
  font-weight: 700;
  font-size: var(--text-base);
  margin-bottom: var(--space-1);
}

.store-card__address {
  color: var(--color-text-secondary);
  font-size: var(--text-sm);
  margin-bottom: var(--space-2);
}

.store-card__hours {
  color: var(--color-primary);
  font-size: var(--text-sm);
  font-weight: 600;
  margin-bottom: var(--space-3);
}

.store-card__features {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.store-feature {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-2);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: 600;
}

/* --- Footer --- */
.site-footer {
  background: var(--color-dark-forest);
  color: rgba(255,255,255,0.8);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-column h4 {
  color: #fff;
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  margin-bottom: var(--space-4);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-column a {
  display: block;
  padding: var(--space-1) 0;
  color: rgba(255,255,255,0.7);
  font-size: var(--text-sm);
  transition: color var(--transition-fast);
}

.footer-column a:hover {
  color: #fff;
}

.footer-accordion {
  display: none;
}

.footer-accordion__item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-accordion__trigger {
  width: 100%;
  text-align: left;
  padding: var(--space-4) 0;
  color: #fff;
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  min-height: 44px;
}

.footer-accordion__icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
}

.footer-accordion__item.is-open .footer-accordion__icon {
  transform: rotate(180deg);
}

.footer-accordion__content {
  display: none;
  padding-bottom: var(--space-4);
}

.footer-accordion__item.is-open .footer-accordion__content {
  display: block;
}

.footer-accordion__content a {
  display: block;
  padding: var(--space-2) 0;
  color: rgba(255,255,255,0.7);
  font-size: var(--text-sm);
}

.footer-accordion__content a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-6);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-bottom p {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-4);
}

.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background: var(--color-primary);
  color: #fff;
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--color-dark-forest);
  color: #fff;
  padding: var(--space-6);
  z-index: 1000;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-8);
}

.cookie-banner.is-hidden {
  display: none;
}

.cookie-banner__content {
  max-width: 600px;
}

.cookie-banner__title {
  font-family: var(--font-heading);
  font-size: var(--text-lg);
  margin-bottom: var(--space-2);
  color: #fff;
}

.cookie-banner__text {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.8);
  line-height: 1.6;
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
}

/* --- Utilities --- */
.text-center { text-align: center; }
.text-primary { color: var(--color-primary); }
.mt-4 { margin-top: var(--space-4); }
.mt-8 { margin-top: var(--space-8); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-8 { margin-bottom: var(--space-8); }
.section-title {
  text-align: center;
  margin-bottom: var(--space-4);
}
.section-subtitle {
  text-align: center;
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  max-width: 600px;
  margin: 0 auto var(--space-4);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .featured-product__card {
    grid-template-columns: 1fr;
  }

  .featured-product__image {
    aspect-ratio: 16 / 9;
  }

  .featured-product__content {
    padding: var(--space-8);
  }

  .promo-grid {
    gap: var(--space-6);
  }

  .ai-card {
    grid-template-columns: 1fr;
    padding: var(--space-8);
  }

  .menu-layout {
    grid-template-columns: 220px 1fr;
    gap: var(--space-6);
  }

  .store-layout {
    grid-template-columns: 1fr;
  }

  .results-list {
    max-height: none;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --text-6xl: 2.5rem;
    --text-5xl: 2rem;
    --text-4xl: 1.75rem;
    --text-3xl: 1.5rem;
  }

  .header-nav {
    display: none;
  }

  .header-actions .btn--secondary,
  .header-actions .btn--primary {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .hero {
    min-height: 400px;
  }

  .hero__image {
    display: none;
  }

  .promo-grid,
  .promo-grid--reverse {
    grid-template-columns: 1fr;
    direction: ltr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    gap: var(--space-6);
  }

  .tiers-grid {
    grid-template-columns: 1fr;
  }

  .partners-grid {
    grid-template-columns: 1fr;
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .store-layout {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    display: none;
  }

  .footer-accordion {
    display: block;
  }

  .cookie-banner {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .search-bar {
    flex-direction: column;
  }

  .search-controls__actions {
    justify-content: center;
  }

  .map-container {
    aspect-ratio: 4 / 3;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--space-4);
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .app-buttons {
    flex-direction: column;
    align-items: center;
  }

  .carousel-card {
    flex: 0 0 160px;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

raw_arguments.content:
/* ============================================
   GreenBean Coffee — Design System & Styles
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Brand Colors */
  --color-primary: #00824A;
  --color-primary-hover: #006B3D;
  --color-primary-light: #E8F5EE;
  --color-primary-lighter: #F0FAF4;
  --color-dark-forest: #32462F;
  --color-warm-cream: #F3CEA1;
  --color-warm-cream-light: #FBF3E0;
  --color-coffee-brown: #6F4E37;
  --color-coffee-dark: #4A3228;
  --color-coffee-light: #D4A574;

  /* Neutral Colors */
  --color-bg: #FAFAF5;
  --color-surface: #FFFFFF;
  --color-text: #1E2D1E;
  --color-text-secondary: #5A6B5A;
  --color-text-muted: #8A9A8A;
  --color-border: #E2E0D8;
  --color-border-light: #F0EDE6;

  /* Accent Colors */
  --color-accent-warm: #D4A574;
  --color-accent-mango: #FFB347;
  --color-accent-lavender: #B39DDB;

  /* Semantic */
  --color-error: #D32F2F;
  --color-success: #2E7D32;

  /* Typography */
  --font-heading: 'DM Serif Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Type Scale */
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.06);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.08), 0 8px 10px -6px rgba(0, 0, 0, 0.04);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --container-max: 1280px;
  --container-wide: 1440px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-primary-hover);
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input, select, textarea {
  font-family: inherit;
  font-size: inherit;
}

/* Focus styles */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: #fff;
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  z-index: 10000;
  font-size: var(--text-sm);
  font-weight: 600;
}

.skip-link:focus {
  top: var(--space-4);
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.2;
  color: var(--color-text);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); }

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container--wide {
  max-width: var(--container-wide);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1.5;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
  min-height: 44px;
}

.btn--primary {
  background: var(--color-primary);
  color: #fff;
  border: 2px solid var(--color-primary);
}

.btn--primary:hover {
  background: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
  color: #fff;
}

.btn--secondary {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn--secondary:hover {
  background: var(--color-primary);
  color: #fff;
}

.btn--dark {
  background: var(--color-dark-forest);
  color: #fff;
  border: 2px solid var(--color-dark-forest);
}

.btn--dark:hover {
  background: #253525;
  border-color: #253525;
}

.btn--cream {
  background: var(--color-warm-cream);
  color: var(--color-coffee-dark);
  border: 2px solid var(--color-warm-cream);
}

.btn--cream:hover {
  background: #ebc488;
  border-color: #ebc488;
}

.btn--ghost {
  background: transparent;
  color: var(--color-primary);
  border: none;
  padding: var(--space-2) var(--space-3);
}

.btn--ghost:hover {
  background: var(--color-primary-light);
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

.btn--sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
  min-height: 36px;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  box-shadow: var(--shadow-sm);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--container-wide);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  color: var(--color-primary);
  text-decoration: none;
  flex-shrink: 0;
}

.header-logo:hover {
  color: var(--color-primary);
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.header-nav a {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: 0.02em;
  transition: color var(--transition-fast);
  position: relative;
  padding: var(--space-1) 0;
}

.header-nav a:hover,
.header-nav a.active {
  color: var(--color-primary);
}

.header-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-primary);
  border-radius: 1px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.header-actions .btn {
  font-size: var(--text-xs);
}

.header-find-store {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
}

.header-find-store:hover {
  color: var(--color-primary);
}

.header-find-store svg {
  width: 18px;
  height: 18px;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: pointer;
}

.menu-toggle svg {
  width: 24px;
  height: 24px;
  color: var(--color-text);
}

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-surface);
  z-index: 99;
  padding: var(--space-6);
  overflow-y: auto;
}

.mobile-nav.is-open {
  display: block;
}

.mobile-nav a {
  display: block;
  padding: var(--space-4) 0;
  font-size: var(--text-lg);
  font-weight: 600;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border-light);
}

.mobile-nav a:hover {
  color: var(--color-primary);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  overflow: hidden;
  min-height: 520px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-primary-lighter) 0%, var(--color-warm-cream-light) 100%);
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 560px;
}

.hero__title {
  font-size: var(--text-6xl);
  margin-bottom: var(--space-6);
  color: var(--color-dark-forest);
}

.hero__cta {
  margin-top: var(--space-6);
}

.hero__image {
  position: absolute;
  right: -5%;
  top: 50%;
  transform: translateY(-50%);
  width: 50%;
  max-width: 600px;
  z-index: 1;
  opacity: 0.15;
}

.hero__image-placeholder {
  width: 100%;
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-coffee-brown) 100%);
  border-radius: var(--radius-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.6);
  font-size: var(--text-2xl);
  font-family: var(--font-heading);
}

/* --- Featured Product --- */
.featured-product {
  padding: var(--space-16) 0;
}

.featured-product__card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.featured-product__image {
  aspect-ratio: 1;
  background: linear-gradient(135deg, #FF9A56 0%, #FF6B6B 50%, #FFE66D 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
}

.featured-product__content {
  padding: var(--space-10) var(--space-10) var(--space-10) 0;
}

.featured-product__tag {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 600;
  margin-bottom: var(--space-4);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.featured-product__title {
  margin-bottom: var(--space-4);
}

.featured-product__body {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

/* --- Promo Sections --- */
.promo-section {
  padding: var(--space-16) 0;
}

.promo-section--cream {
  background: var(--color-warm-cream-light);
}

.promo-section--green {
  background: var(--color-primary);
  color: #fff;
}

.promo-section--forest {
  background: var(--color-dark-forest);
  color: #fff;
}

.promo-section--forest h2,
.promo-section--green h2 {
  color: #fff;
}

.promo-section--forest p,
.promo-section--green p {
  color: rgba(255,255,255,0.85);
}

.promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
  align-items: center;
}

.promo-grid--reverse {
  direction: rtl;
}

.promo-grid--reverse > * {
  direction: ltr;
}

.promo-image {
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  color: rgba(255,255,255,0.6);
}

.promo-image--mango {
  background: linear-gradient(135deg, #FF9A56 0%, #FFD93D 100%);
}

.promo-image--lavender {
  background: linear-gradient(135deg, #B39DDB 0%, #E1BEE7 50%, #F8BBD0 100%);
}

.promo-image--spring {
  background: linear-gradient(135deg, #81C784 0%, #A5D6A7 50%, #C8E6C9 100%);
}

.promo-image--nondairy {
  background: linear-gradient(135deg, var(--color-primary) 0%, #4CAF50 100%);
}

.promo-content {
  padding: var(--space-4) 0;
}

.promo-content__tag {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 600;
  margin-bottom: var(--space-4);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.promo-content__title {
  margin-bottom: var(--space-4);
}

.promo-content__body {
  color: var(--color-text-secondary);
  font-size: var(--text-lg);
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

.promo-section--forest .promo-content__tag,
.promo-section--green .promo-content__tag {
  background: rgba(255,255,255,0.2);
  color: #fff;
}

/* --- AI Recommendation --- */
.ai-recommendation {
  padding: var(--space-16) 0;
}

.ai-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  background: linear-gradient(135deg, var(--color-dark-forest) 0%, #1a2e1a 100%);
  border-radius: var(--radius-xl);
  overflow: hidden;
  color: #fff;
  padding: var(--space-12);
}

.ai-card h2 {
  color: #fff;
}

.ai-card p {
  color: rgba(255,255,255,0.8);
  font-size: var(--text-lg);
  line-height: 1.7;
}

.ai-card__visual {
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 1;
  background: rgba(255,255,255,0.08);
  border-radius: var(--radius-xl);
  font-family: var(--font-heading);
  font-size: var(--text-3xl);
  color: rgba(255,255,255,0.4);
}

/* --- Menu Page --- */
.menu-page {
  padding: var(--space-8) 0 var(--space-16);
}

.breadcrumb {
  padding: var(--space-4) 0;
  font-size: var(--text-sm);
  color: var(--color-text-muted);
}

.breadcrumb a {
  color: var(--color-text-secondary);
}

.breadcrumb span {
  margin: 0 var(--space-2);
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-8);
  align-items: start;
}

.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-8));
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  box-shadow: var(--shadow-md);
}

.menu-sidebar__section {
  margin-bottom: var(--space-6);
}

.menu-sidebar__heading {
  font-family: var(--font-body);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-muted);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--color-border-light);
}

.menu-sidebar__link {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.menu-sidebar__link:hover,
.menu-sidebar__link.active {
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-weight: 600;
}

.menu-content__heading {
  font-size: var(--text-3xl);
  margin-bottom: var(--space-8);
  padding-bottom: var(--space-4);
  border-bottom: 2px solid var(--color-primary-light);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-6);
  margin-bottom: var(--space-12);
}

.menu-item {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.menu-item:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.menu-item__image {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  color: rgba(255,255,255,0.6);
  font-size: var(--text-lg);
}

.menu-item__image--coffee {
  background: linear-gradient(135deg, #8D6E63 0%, #6F4E37 100%);
}

.menu-item__image--cold {
  background: linear-gradient(135deg, #4FC3F7 0%, #0288D1 100%);
}

.menu-item__image--matcha {
  background: linear-gradient(135deg, #66BB6A 0%, #388E3C 100%);
}

.menu-item__image--refresher {
  background: linear-gradient(135deg, #FF7043 0%, #F4511E 100%);
}

.menu-item__image--food {
  background: linear-gradient(135deg, #FFB74D 0%, #F57C00 100%);
}

.menu-item__image--bakery {
  background: linear-gradient(135deg, #D4A574 0%, #A1887F 100%);
}

.menu-item__name {
  padding: var(--space-3) var(--space-4);
  font-weight: 600;
  font-size: var(--text-sm);
}

.menu-section-divider {
  margin: var(--space-12) 0 var(--space-8);
  padding-top: var(--space-8);
  border-top: 1px solid var(--color-border-light);
}

/* --- Rewards Page --- */
.rewards-hero {
  padding: var(--space-16) 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%);
  color: #fff;
  text-align: center;
}

.rewards-hero h1 {
  color: #fff;
  font-size: var(--text-5xl);
  margin-bottom: var(--space-4);
}

.rewards-hero p {
  color: rgba(255,255,255,0.85);
  font-size: var(--text-lg);
  max-width: 600px;
  margin: 0 auto var(--space-8);
}

.how-it-works {
  padding: var(--space-16) 0;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
  margin-top: var(--space-12);
}

.step-card {
  text-align: center;
  padding: var(--space-8);
}

.step-card__number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  margin: 0 auto var(--space-6);
}

.step-card h3 {
  margin-bottom: var(--space-3);
}

.step-card p {
  color: var(--color-text-secondary);
  line-height: 1.7;
}

/* Status Tiers */
.status-tiers {
  padding: var(--space-16) 0;
  background: var(--color-primary-lighter);
}

.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
  margin-top: var(--space-12);
}

.tier-card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
  transition: all var(--transition-base);
}

.tier-card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

.tier-card--gold {
  border: 2px solid #FFD700;
}

.tier-card--reserve {
  border: 2px solid var(--color-coffee-dark);
  background: linear-gradient(180deg, #3a2a1e 0%, var(--color-dark-forest) 100%);
  color: #fff;
}

.tier-card--reserve h3,
.tier-card--reserve h4 {
  color: #fff;
}

.tier-card--reserve p,
.tier-card--reserve li {
  color: rgba(255,255,255,0.85);
}

.tier-card__badge {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: var(--space-4);
}

.tier-card--green .tier-card__badge {
  background: var(--color-primary-light);
  color: var(--color-primary);
}

.tier-card--gold .tier-card__badge {
  background: #FFF8E1;
  color: #F9A825;
}

.tier-card--reserve .tier-card__badge {
  background: rgba(255,255,255,0.15);
  color: var(--color-warm-cream);
}

.tier-card h3 {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-2);
}

.tier-card__threshold {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  margin-bottom: var(--space-6);
}

.tier-card--reserve .tier-card__threshold {
  color: rgba(255,255,255,0.6);
}

.tier-card__benefits {
  list-style: none;
}

.tier-card__benefits li {
  padding: var(--space-2) 0;
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.tier-card__benefits li::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-primary);
  flex-shrink: 0;
}

.tier-card--reserve .tier-card__benefits li::before {
  background: var(--color-warm-cream);
}

/* Redemption Tabs */
.redemption-section {
  padding: var(--space-16) 0;
}

.redemption-tabs {
  display: flex;
  gap: var(--space-2);
  overflow-x: auto;
  padding-bottom: var(--space-4);
  margin-bottom: var(--space-8);
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}

.redemption-tab {
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  white-space: nowrap;
  background: var(--color-surface);
  color: var(--color-text-secondary);
  border: 2px solid var(--color-border);
  cursor: pointer;
  transition: all var(--transition-base);
  min-height: 44px;
  display: flex;
  align-items: center;
}

.redemption-tab:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.redemption-tab.active {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}

.redemption-content {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-md);
  min-height: 200px;
}

.redemption-panel {
  display: none;
}

.redemption-panel.active {
  display: block;
  animation: fadeIn var(--transition-base);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-panel__stars {
  font-size: var(--text-4xl);
  color: var(--color-primary);
  font-family: var(--font-heading);
  margin-bottom: var(--space-4);
}

.redemption-panel__reward {
  font-size: var(--text-xl);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.redemption-panel__value {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
}

/* Partnerships */
.partnerships {
  padding: var(--space-16) 0;
  background: var(--color-warm-cream-light);
}

.partners-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
  margin-top: var(--space-12);
}

.partner-card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-md);
  display: flex;
  gap: var(--space-6);
  align-items: start;
}

.partner-card__icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-lg);
  background: var(--color-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: var(--text-2xl);
  color: var(--color-primary);
}

.partner-card h4 {
  margin-bottom: var(--space-2);
}

.partner-card p {
  color: var(--color-text-secondary);
  font-size: var(--text-sm);
  line-height: 1.6;
}

/* App Download */
.app-download {
  padding: var(--space-16) 0;
  text-align: center;
}

.app-download__visual {
  max-width: 400px;
  margin: var(--space-8) auto;
  aspect-ratio: 3 / 4;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark-forest) 100%);
  border-radius: var(--radius-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.5);
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
}

.app-buttons {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  margin-top: var(--space-6);
}

/* Terms */
.terms-section {
  padding: var(--space-8) 0 var(--space-16);
}

.terms-section p {
