  <script>
    function toggleMobileNav() {
      const nav = document.getElementById('mobileNav');
      const toggle = document.querySelector('.menu-toggle');
      const isOpen = nav.classList.toggle('is-open');
      toggle.setAttribute('aria-expanded', isOpen);
    }

    // Footer accordion
    document.querySelectorAll('.footer-accordion__trigger').forEach(trigger => {
      trigger.addEventListener('click', () => {
        const item = trigger.parentElement;
        const isOpen = item.classList.toggle('is-open');
        trigger.setAttribute('aria-expanded', isOpen);
      });
    });

    // Search suggestions
    const searchInput = document.getElementById('storeSearch');
    const suggestions = document.getElementById('searchSuggestions');

    searchInput.addEventListener('input', () => {
      const value = searchInput.value.toLowerCase().trim();
      if (value.length > 0) {
        const items = suggestions.querySelectorAll('li');
        let hasVisible = false;
        items.forEach(item => {
          const text = item.getAttribute('data-value').toLowerCase();
          if (text.includes(value)) {
            item.style.display = 'flex';
            hasVisible = true;
          } else {
            item.style.display = 'none';
          }
        });
        suggestions.classList.toggle('is-visible', hasVisible);
      } else {
        suggestions.classList.remove('is-visible');
      }
    });

    searchInput.addEventListener('focus', () => {
      if (searchInput.value.trim().length > 0) {
        suggestions.classList.add('is-visible');
      }
    });

    suggestions.querySelectorAll('li').forEach(item => {
      item.addEventListener('click', () => {
        searchInput.value = item.getAttribute('data-value');
        suggestions.classList.remove('is-visible');
      });
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.search-input-wrapper')) {
        suggestions.classList.remove('is-visible');
      }
    });

    // Order type toggle
    document.querySelectorAll('.order-type-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.order-type-btn').forEach(b => {
          b.classList.remove('active');
          b.setAttribute('aria-checked', 'false');
        });
        btn.classList.add('active');
        btn.setAttribute('aria-checked', 'true');
      });
    });

    // Filter toggle
    const filterToggle = document.getElementById('filterToggle');
    const filterPanel = document.getElementById('filterPanel');

    filterToggle.addEventListener('click', () => {
      const isOpen = filterPanel.classList.toggle('is-open');
      filterToggle.setAttribute('aria-expanded', isOpen);
    });

    function applyFilters() {
      filterPanel.classList.remove('is-open');
      filterToggle.setAttribute('aria-expanded', 'false');
    }
  </script>
